fn host_row(variant:Variant,j:usize)->usize {
    if let Variant::D=variant {
        return HOST_COEFFICIENT_TO_ROW[j] as usize;
    }
    let mut out=0usize;
    let mut d=0usize;
    while d<5 {
        out|=((j>>((2*d) as u32))&3) << ((2*crate::transport::TAU[d]) as u32);
        d+=1;
    }
    out
}

